public List<List<int>> Permute(int[] nums)
{
    if (nums.Length == 1)
        return new List<List<int>> { new List<int> { nums[0] } };

    var permutations = new List<List<int>>();
    for (var i = 0; i < nums.Length; i++)
    {
        var n = nums[i];
        var remainingNums = nums.Take(i).Concat(nums.Skip(i + 1));
        foreach (var p in Permute(remainingNums))
            permutations.Add(new List<int> { n }.Concat(p));
    }
    return permutations;
}

