public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<List<Integer>> recursiveResult = permute(Arrays.copyOf(nums, i).concat(Arrays.copyOf(nums, i + 1)));
