        List<List<Integer>> result = new ArrayList<>();
        if (nums.length == 0) {
            return result;
        }
        permuteHelper(nums, result, new ArrayList<>(), new boolean[nums.length]);
        return result;
    }

private void permuteHelper(int[] nums, List<List<Integer>> result, List<Integer> tempList, boolean[] used) {
        if (tempList.size() == nums.length) {
            result.add(new ArrayList<>(tempList));
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (used[i]) {
                continue;
            }
            tempList.add(nums[i]);
            used[i] = true;
            permuteHelper(nums, result, tempList, used);
            tempList.remove(tempList.size() - 1);
            used[i] = false;
        }
    }

public static List<List<Integer>> permute(int[] nums) {
