    // Initialize a map to store the lengths of strings
    Map<String, Integer> lengths = new HashMap<>();

    // Iterate through the strings and calculate their lengths
    for (String string : strings) {
        lengths.put(string, string.length());
    }

    // Initialize a variable to store the largest string
    String largest = "";

    // Iterate through the strings and their lengths
    for (Map.Entry<String, Integer> entry : lengths.entrySet()) {
        String string = entry.getKey();
        int length = entry.getValue();

        // Check if the string is longer than the current largest string
        if (length > largest.length()) {
            largest = string;
