private void floodFill(char[][] grid, int row, int col, char color) {
    if (grid[row][col] != '@') return;
    grid[row][col] = color;
    if (row > 0) floodFill(grid, row - 1, col, color);
    if (row < grid.length - 1) floodFill(grid, row + 1, col, color);
    if (col > 0) floodFill(grid, row, col - 1, color);
    if (col < grid[row].length - 1) floodFill(grid, row, col + 1, color);
}

public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    Set<Integer> depositedPlots = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !depositedPlots.contains(i * grid.length + j)) {
                numDeposits++;
                bfs(grid, i, j, depositedPlots);
            }
        }
    }
    return numDeposits;
}

private static void bfs(char[][] grid, int x, int y, Set<Integer> depositedPlots) {
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{x, y});
    depositedPlots.add(x * grid.length + y);
    while (!queue.isEmpty()) {
        int[] curr = queue.remove();
        int currX = curr[0];
        int currY = curr[1];
        if (grid[currX][currY] == '@') {
            grid[currX][currY] = ' ';
            int[] neighbors = getNeighbors(grid, currX, currY);
            for (int[] neighbor : neighbors) {
                if (grid[neighbor[0]][neighbor[1]] == '@' && !depositedPlots.contains(neighbor[0] * grid.length + neighbor[1])) {
                    queue.add(neighbor);
                    depositedPlots.add(neighbor[0] * grid.length + neighbor[1]);
                }
            }
        }
    }
}

private static int[][] getNeighbors(char[][] grid, int x, int y) {
    int[][] neighbors = new int[8][2];
    neighbors[0] = new int[]{x - 1, y};
    neighbors[1] = new int[]{x + 1, y};
    neighbors[2] = new int[]{x, y - 1};
    neighbors[3] = new int[]{x, y + 1};
    neighbors[4] = new int[]{x - 1, y - 1};
    neighbors[5] = new int[]{x + 1, y - 1};
    neighbors[6] = new int[]{x - 1, y + 1};
    neighbors[7] = new int[]{x + 1, y + 1};
    return neighbors;
}

