public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a boolean array to keep track of which n-tersections have been visited
  boolean[] visited = new boolean[n];

  // Set the starting n-tersection as visited
  visited[start[0] * n + start[1]] = true;

  // Use a queue to traverse the n-tersections in the order of their distance from the starting n-tersection
  Queue<Integer> queue = new ArrayDeque<>();
  queue.add(start[0] * n + start[1]);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the next n-tersection to visit
    int current = queue.remove();

    // Check if the current n-tersection is the ending n-tersection
    if (current == end[0] * n + end[1]) {
      return "can be travelled";
    }

    // Loop through all paths from the current n-tersection
    for (int[] path : paths) {
      // Check if the path is valid
      if (path[0] == current && !visited[path[1]]) {
        // Set the next n-tersection as visited
        visited[path[1]] = true;

        // Add the next n-tersection to the queue
        queue.add(path[1]);
      }
    }
  }

  // If the queue is empty and the ending n-tersection is not visited, return "cannot be travelled"
  return "cannot be travelled";
}

