    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Queue for BFS
    Queue<Integer[]> queue = new ArrayDeque<>();

    // Initialize the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Add the starting n-tersection to the queue
    queue.add(new Integer[]{start[0], start[1]});

    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        Integer[] curr = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (curr[0] == end[0] && curr[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through all adjacent n-tersections
        for (int i = 0; i < n; i++) {
            // If the current n-tersection is not visited and has a path to an adjacent n-tersection
            if (!visited[curr[0]][i] && paths[curr[0]][i] != 0) {
                // Mark the adjacent n-tersection as visited
                visited[curr[0]][i] = true;

                // Add the adjacent n-tersection to the queue
                queue.add(new Integer[]{curr[0], i});
            }
        }
    }

    // If the starting n-tersection is not the ending n-tersection, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a set to store visited n-tersections
  Set<Integer> visited = new HashSet<>();

  // Initialize a queue for Breadth-First Search
  Queue<Integer> queue = new LinkedList<>();

  // Add the starting n-tersection to the queue and visited set
  queue.add(start);
  visited.add(start);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Dequeue a n-tersection from the queue
    int current = queue.remove();

    // If the current n-tersection is the ending n-tersection, return "can be travelled"
    if (current == end) {
      return "can be travelled";
    }

    // Get all reachable n-tersections from the current n-tersection
    int[] reachable = paths[current];

    // Loop through all reachable n-tersections
    for (int i = 0; i < reachable.length; i++) {
      // If the n-tersection is not already visited, add it to the queue and visited set
      if (!visited.contains(reachable[i])) {
        queue.add(reachable[i]);
        visited.add(reachable[i]);
      }
    }
  }

  // If the ending n-tersection was not found, return "cannot be travelled"
  return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < Math.min(word1.length(), word2.length()); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }
    int denominator = word1.length() + word2.length();
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    if (a == 0) return b;
    return gcd(b % a, a);
}

