        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int numerator = commonLetters;
    int denominator = word1.length() + word2.length() - commonLetters;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

public static String appx(String word1, String word2){
    if(word1 == null || word2 == null) {
        throw new IllegalArgumentException("Approximate value cannot be computed for null words.");
    }

    // Calculate the sum of the lengths of the two words
    int sum = word1.length() + word2.length();

    // Initialize common letter count
    int commonLetters = 0;

    // Loop through each character in both words
    for(int i = 0; i < word1.length(); i++){
        for(int j = 0; j < word2.length(); j++){
            // Check if they are common letters
            if(word1.charAt(i) == word2.charAt(j) && commonLetters < 2) {
                commonLetters++;
            }
        }
    }

    if(commonLetters == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Calculate the approximate value
    int approximateValue = commonLetters * 100 / sum;

    // Format the result as a reduced fraction
    String result = "appx(" + word1 + ", " + word2 + ") = ";
    if(commonLetters == 1) {
        result += approximateValue + "/" + sum;
    } else {
        result += approximateValue + "/" + (sum - commonLetters) + "," + commonLetters + "/" + sum;
    }

    return result;
}

