public double trimMean(int[] arr) {

    Arrays.sort(arr);
    int n = arr.length;

    int numberRemoved = (int) (n * 0.05);

    int left = numberRemoved * 2;
    int right = n - left - 1;

    double total = 0;
    for (int i = left; i <= right; ++i) {
        total += arr[i];
    }

    return total / (right - left + 1);
}

