    int n = arr.length;
    int start = (int) Math.ceil(0.05 * n);
    int end = (int) Math.floor(0.95 * n);
    double sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    return sum / (end - start + 1);
}

