public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }
    int[] sum = new int[arr.length / 2];
    for (int i = 0; i < arr.length; i += 2) {
        sum[i] = arr[i] + arr[i + 1];
    }
    for (int i = 0; i < sum.length; i++) {
        if (sum[i] % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // step 1: if the length of the input array is not even, return false
    if (arr.length % 2 != 0) {
        return false;
    }

    // step 2: calculate the sum of the input array
    int sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }

    // step 3: if the sum of the input array is not divisible by k, return false
    if (sum % k != 0) {
        return false;
    }

    // step 4: sort the input array in ascending order
    Arrays.sort(arr);

    // step 5: pair up the elements of the sorted array
    for (int i = 0; i < arr.length - 1; i += 2) {
        int sumOfPair = arr[i] + arr[i + 1];
        if (sumOfPair % k != 0) {
            return false;
        }
    }

    // step 6: if all pairs have a sum divisible by k, return true
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int pairs = arr.length / 2;
    boolean[] pair = new boolean[pairs];
    for (int i = 0; i < arr.length; i++) {
        int j = (i + 1) % pairs;
        if (arr[i] % k == 0 && arr[j] % k == 0) {
            if (j < i) {
                pair[j] = true;
            } else {
                pair[i] = true;
            }
        }
    }
    for (int i = 0; i < pairs; i++) {
        if (!pair[i]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k){
    int len = arr.length;
    boolean possible=true;
    ///check whether n/2 exists
    if(len % 2 != 0){
        return false;
    }
    ///check whether all elements exists in the range 0 to k - 1
    for(int i=0;i<len;i++){
        if(arr[i] >= k){
            return false;
        }
    }
    Arrays.sort(arr);
    for(int i=0;i<len/2;i++){
        int sum = arr[i] + arr[len - i - 1];
        if(sum % k != 0){
            return false;
        }
    }
    return possible;
}

