}

def minTime(n, edges, hasApple):
    # Create a graph with n nodes and edges
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Perform a dfs to find the minimum time required to collect all the apples and return to node 0
    visited = [False] * n
    min_time = 0
    def dfs(curr, parent):
        nonlocal min_time
        visited[curr] = True
        if hasApple[curr]:
            min_time += 2
        for next in graph[curr]:
            if not visited[next] and next != parent:
                dfs(next, curr)
    dfs(0, -1)
    return min_time

def minTime(n, edges, hasApple):
    # Create a graph with n nodes and edges
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize the min time required to collect all apples and return to node 0
    min_time = 0

    # Perform a depth first search starting from node 0
    visited = [False] * n
    has_apple = [False] * n
    stack = [0]
    while stack:
        node = stack.pop()
        if not visited[node]:
            visited[node] = True
            if hasApple[node]:
                has_apple[node] = True
                min_time += 2
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    stack.append(neighbor)

    # If there are still apples that have not been collected, return to node 0 to collect them
    if any(has_apple):
        min_time += 2

    return min_time

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> tree = new HashMap<>();
    for (int i = 0; i < edges.length; i++) {
        tree.putIfAbsent(edges[i][0], new ArrayList<>());
        tree.putIfAbsent(edges[i][1], new ArrayList<>());
        tree.get(edges[i][0]).add(edges[i][1]);
        tree.get(edges[i][1]).add(edges[i][0]);
    }
    return dfs(tree, 0, -1, hasApple);
}

private int dfs(Map<Integer, List<Integer>> tree, int node, int parent, boolean[] hasApple) {
    int minTime = 0;
    boolean hasAppleHere = hasApple[node];
    for (int child : tree.getOrDefault(node, Collections.emptyList())) {
        if (child != parent) {
            minTime = Math.max(minTime, dfs(tree, child, node, hasApple));
        }
    }
    if (hasAppleHere) {
        minTime += 2;
    }
    return minTime;
}

public static String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < arr.length) {
        char c = arr[i];
        result.append(c);
