public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int operations = 0;
    while (!allEqual(arr)) {
        operations++;
        int minVal = findMin(arr);
        int maxVal = findMax(arr);
        arr[minVal] -= 1;
        arr[maxVal] += 1;
    }
    return operations;
}

