public int minOperations(String[] logs) {
    int minOperations = 0;
    String currentFolder = "";
    for (String log : logs) {
        if (log.equals("../")) {
            minOperations++;
            continue;
        }
        if (!log.startsWith("d")) {
            continue;
        }
        int slashIndex = log.lastIndexOf('/');
        String newFolder = log.substring(slashIndex);
        if (currentFolder.isEmpty()) {
            currentFolder = newFolder;
        } else {
            currentFolder = currentFolder.substring(0, currentFolder.lastIndexOf('/')) + newFolder;
        }
        minOperations++;
    }
    return minOperations;
}

public int minOperations(String[] logs) {
    int step = 0, root = 0;
    for (String log : logs) {
        if (log.equals("../")) {
            if (step > 0) step -= 2;
        } else if (log.equals("./")) {
            continue;
        } else if (log.startsWith("d")) {
            if (log.length() == 2) {
                step += 2;
            } else {
                root++;
            }
        }
    }
    return step + root - 1;
}

