public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    int remaining = n - 1;
    while (remaining >= 0) {
        int quo = k / remaining;
        int charValue = Math.max(1, quo - 25);
        if (charValue > 1) {
            sb.append((char)('a' + (charValue - 1)));
        }
