public String getSmallestString(int n, int k) {
        // Calculate the largest character that will be included in the string
        char largestChar = (char) ((k - 1) % 26 + 'a');
        // Create a string of the largest character repeated n times
        String smallestString = new String(new char[n]).replace("\0", String.valueOf(largestChar));
        // Add additional characters to the string to match the remaining value
        for (int i = n - 1; i >= 0; i--) {
            int value = (int) smallestString.charAt(i) - 'a' + 1;
            if (value > k) {
                smallestString = smallestString.substring(0, i) + String.valueOf((char) ('a' + k)) + smallestString.substring(i + 1);
                break;
            }
            k -= value;
        }
        return smallestString;
    }

