    // Initialize the value of the string
    int value = 0;

    while (string.length() < n) {
        // Find the first character that can be added to the string
        // without exceeding the given k value
        char newChar = 'a';
        int i = 0;
        while (value + i + 1 > k) {
            newChar++;
            i++;
        }
        string = string + newChar;
        value += i + 1;
    }

    // If the string is longer than the given length, remove the extra characters
    if (string.length() > n) {
        string = string.substring(0, n);
    }

    return string;
}

