            // For each element in the HashMap, check if it can be added to the current permutation
            int element = entry.getKey();
            int count = entry.getValue();
            if (count > 0 && elementCounts.get(element) != null) {
                // If the element is not already in the current permutation, add it
                if (!current[index].contains(element)) {
                    current[index] = element;
                    elementCounts.put(element, count - 1);
                    permute(A, index + 1, permutations, current, elementCounts);
                    elementCounts.put(element, count);
                }
            }
        }
    }

