public static boolean isBoomerang(int[][] points) {
    // checking if the points form a straight line
    if ((points[1][0] - points[0][0]) * (points[2][1] - points[0][1])
            == (points[1][1] - points[0][1]) * (points[2][0] - points[0][0])) {
        return false;
    }

    // checking if the points are in the same line
    for (int i = 0; i < points.length; i++) {
        if ((points[i][0] - points[(i + 1) % points.length][0]) * (points[(i + 2) % points.length][1]
                - points[(i + 1) % points.length][1])
                == (points[i][1] - points[(i + 1) % points.length][1]) * (points[(i + 2) % points.length][0]
