public static int minPerfectSquareSum(int n) {
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int square = i * i;
        if (square <= n) {
            perfectSquares.add(square);
        }
    }
    int minSum = Integer.MAX_VALUE;
    for (int i = 0; i < perfectSquares.size(); i++) {
        int sum = perfectSquares.get(i);
        for (int j = i + 1; j < perfectSquares.size(); j++) {
            int candidateSum = sum + perfectSquares.get(j);
            if (candidateSum <= n) {
                minSum = Math.min(minSum, candidateSum);
            } else {
                break;
            }
        }
    }
    return minSum;
}

int minPerfectSquareSum(int n) {

    // Create an array to store the perfect squares less than or equal to n
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        perfectSquares.add(i * i);
    }

    // Use dynamic programming to find the minimum number of perfect squares that sum up to n
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 0; j < perfectSquares.size(); j++) {
            min = Math.min(min, dp[i - perfectSquares.get(j)] + 1);
        }
        dp[i] = min;
    }

    return dp[n];
}

